head.b:skin:
/* CSS RESET ĐẶC TRỊ LỖI KHOẢNG CÁCH BLOGSPOT - LIGHT THEME (GIAO DIỆN TRẮNG CHUẨN WEB CŨ) */
* { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Be Vietnam Pro', sans-serif; }
html, body { background-color: #f8fafc; color: #0f172a; min-height: 100vh; line-height: 1.5; }

.blogspot-anti-break br { display: none !important; }
.blogspot-anti-break p, .blogspot-anti-break h3, .blogspot-anti-break h4 { margin: 0 !important; padding: 0 !important; }
.blogspot-anti-break span, .blogspot-anti-break div { border: none; }

/* LAYOUT & UTILITIES */
.container { max-width: 1200px; margin: 0 auto; padding: 0 1.2rem; }
.gradient-text-orange { background: linear-gradient(135deg, #ea580c, #f59e0b); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }

/* HEADER & NAVBAR (WHITE LIGHT THEME) */
.site-header { position: sticky; top: 0; z-index: 100; background: #ffffff; border-bottom: 1px solid #e2e8f0; box-shadow: 0 4px 15px rgba(0,0,0,0.03); padding: 0.85rem 0; }
.nav-wrap { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.brand-logo { display: flex; align-items: center; gap: 0.6rem; text-decoration: none; font-size: 1.4rem; font-weight: 800; color: #0f172a; }
.cart-btn-trigger { position: relative; background: linear-gradient(135deg, #ea580c, #f59e0b); border: none; color: #ffffff; padding: 0.6rem 1.3rem; border-radius: 99px; font-weight: 700; cursor: pointer; display: flex; align-items: center; gap: 0.5rem; box-shadow: 0 4px 14px rgba(234, 88, 12, 0.25); }
.cart-badge { background: #ef4444; color: #ffffff; font-size: 0.75rem; font-weight: 800; width: 20px; height: 20px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; }

/* HERO FEATURED BANNER */
.hero-sec { margin: 1.5rem 0; }
.hero-card { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 1.2rem; padding: 1.5rem; display: grid; grid-template-columns: 1fr 1.2fr; gap: 1.5rem; align-items: center; box-shadow: 0 4px 20px rgba(0,0,0,0.04); }
.hero-img img { width: 100%; max-height: 280px; object-fit: cover; border-radius: 0.8rem; border: 1px solid #e2e8f0; }
.badge-hot { background: #fef2f2; color: #ef4444; border: 1px solid #fecaca; padding: 0.3rem 0.8rem; border-radius: 99px; font-size: 0.8rem; font-weight: 700; display: inline-block; }

/* CATEGORY CHIPS */
.chip-bar { display: flex; gap: 0.6rem; overflow-x: auto; padding: 0.8rem 0; margin-bottom: 1.5rem; }
.chip-btn { background: #ffffff; border: 1px solid #cbd5e1; color: #475569; padding: 0.55rem 1.1rem; border-radius: 99px; white-space: nowrap; cursor: pointer; transition: all 0.2s; font-weight: 600; box-shadow: 0 2px 6px rgba(0,0,0,0.02); }
.chip-btn.active, .chip-btn:hover { background: #ea580c; color: #ffffff; border-color: #ea580c; box-shadow: 0 4px 12px rgba(234, 88, 12, 0.25); }

/* PRODUCTS GRID CATALOG (LIGHT MODE) */
.grid-catalog { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 1.5rem; margin-bottom: 3rem; }
.product-card { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 1rem; overflow: hidden; display: flex; flex-direction: column; transition: transform 0.2s, box-shadow 0.2s; box-shadow: 0 4px 15px rgba(0,0,0,0.03); }
.product-card:hover { transform: translateY(-4px); box-shadow: 0 12px 25px rgba(0,0,0,0.08); border-color: #f59e0b; }
.card-img-wrap { position: relative; width: 100%; aspect-ratio: 4/3; background: #f1f5f9; overflow: hidden; }
.card-img-wrap img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; }
.badge-cat { position: absolute; top: 10px; left: 10px; background: #fef3c7; color: #d97706; border: 1px solid #fde68a; font-size: 0.75rem; font-weight: 700; padding: 0.2rem 0.6rem; border-radius: 99px; }
.card-body { padding: 1.1rem; display: flex; flex-direction: column; flex: 1; justify-content: space-between; }
.card-title { font-size: 1.05rem; font-weight: 700; color: #0f172a; margin-bottom: 0.6rem; cursor: pointer; line-height: 1.3; }
.price-row { display: flex; align-items: center; justify-content: space-between; margin-bottom: 1rem; }
.price-val { font-size: 1.2rem; font-weight: 800; color: #d97706; }
.deposit-tag { font-size: 0.8rem; color: #0284c7; background: #e0f2fe; border: 1px solid #bae6fd; padding: 0.15rem 0.5rem; border-radius: 6px; font-weight: 600; }
.card-actions { display: flex; gap: 0.6rem; }
.btn-primary { background: linear-gradient(135deg, #f59e0b, #ea580c); color: #ffffff; border: none; padding: 0.65rem 1rem; border-radius: 10px; font-weight: 700; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 0.4rem; box-shadow: 0 4px 12px rgba(234, 88, 12, 0.25); }
.btn-secondary { background: #f1f5f9; color: #334155; border: 1px solid #cbd5e1; padding: 0.65rem 1rem; border-radius: 10px; font-weight: 600; cursor: pointer; }

/* SINGLE PRODUCT DETAIL VIEW (LIGHT THEME MATCHING ANH 1 EXACTLY) */
.product-detail-card { background: #ffffff; border: 1px solid #e2e8f0; border-radius: 20px; padding: 2rem; margin-bottom: 3rem; box-shadow: 0 10px 30px rgba(0,0,0,0.05); display: grid; grid-template-columns: 1fr 1fr; gap: 2.2rem; align-items: start; }

.gallery-main-wrap { position: relative; width: 100%; aspect-ratio: 4/3; background: #000; border-radius: 16px; overflow: hidden; border: 1px solid #cbd5e1; }
.gallery-main-wrap img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; }
.zoom-badge { position: absolute; bottom: 12px; right: 12px; background: rgba(15,23,42,0.85); color: #ffffff; font-size: 0.8rem; font-weight: 600; padding: 0.4rem 0.8rem; border-radius: 8px; backdrop-filter: blur(4px); cursor: pointer; }

.thumbs-row { display: flex; gap: 0.6rem; overflow-x: auto; margin-top: 1rem; padding-bottom: 0.4rem; }
.thumb-item { width: 68px; height: 68px; border-radius: 10px; border: 2px solid #e2e8f0; object-fit: cover; cursor: pointer; transition: all 0.2s; flex-shrink: 0; }
.thumb-item.active, .thumb-item:hover { border-color: #ea580c; box-shadow: 0 0 10px rgba(234, 88, 12, 0.4); transform: scale(1.05); }

.detail-info-col { display: flex; flex-direction: column; gap: 1rem; }
.badge-cat-light { background: #fef3c7; color: #d97706; border: 1px solid #fde68a; border-radius: 99px; padding: 0.25rem 0.8rem; font-size: 0.8rem; font-weight: 700; align-self: flex-start; }
.detail-title { font-size: 1.8rem; font-weight: 900; color: #0f172a; line-height: 1.25; }

/* KHUNG GIÁ THANH TOÁN TỔNG CỘNG (CHUẨN ANH 1) */
.price-box-light { background: #fef9c3; border: 1px solid #fef08a; border-radius: 14px; padding: 1.1rem 1.4rem; }
.price-box-label { font-size: 0.9rem; font-weight: 600; color: #78350f; }
.price-box-val { font-size: 2.2rem; font-weight: 900; color: #d97706; margin-top: 0.2rem; }

.detail-body-text { color: #334155; font-size: 0.95rem; line-height: 1.6; border-bottom: 1px solid #f1f5f9; padding-bottom: 1rem; }

/* OPTION SELECTOR GROUPS */
.opt-group { display: flex; flex-direction: column; gap: 0.5rem; }
.opt-label { font-size: 0.95rem; font-weight: 700; color: #0f172a; }
.opt-label span { color: #d97706; }
.opt-pills { display: flex; flex-wrap: wrap; gap: 0.6rem; }
.opt-pill { background: #ffffff; border: 1px solid #cbd5e1; color: #334155; padding: 0.55rem 1.2rem; border-radius: 99px; font-size: 0.9rem; font-weight: 600; cursor: pointer; transition: all 0.2s; display: flex; align-items: center; gap: 0.4rem; }
.opt-pill.active { background: #fef9c3; border: 2px solid #f59e0b; color: #92400e; font-weight: 700; box-shadow: 0 2px 8px rgba(245, 158, 11, 0.2); }
.dot-color { width: 12px; height: 12px; border-radius: 50%; display: inline-block; }

/* BUY ROW */
.buy-control-row { display: flex; items-center; gap: 1rem; margin-top: 0.5rem; }
.qty-box { display: flex; align-items: center; border: 1px solid #cbd5e1; border-radius: 12px; background: #f8fafc; overflow: hidden; }
.qty-btn { width: 40px; height: 44px; border: none; background: transparent; font-size: 1.2rem; font-weight: 700; color: #0f172a; cursor: pointer; }
.qty-input { width: 44px; height: 44px; border: none; background: transparent; text-align: center; font-size: 1.05rem; font-weight: 800; color: #0f172a; }
.btn-buy-now-detail { flex: 1; background: linear-gradient(135deg, #f59e0b, #ea580c); color: #ffffff; border: none; padding: 0.9rem 1.5rem; border-radius: 12px; font-size: 1.1rem; font-weight: 800; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 0.6rem; box-shadow: 0 6px 20px rgba(234, 88, 12, 0.35); }

/* MODALS & CART DRAWER (LIGHT MODE) */
.modal-overlay { position: fixed; inset: 0; background: rgba(15, 23, 42, 0.75); backdrop-filter: blur(8px); z-index: 1000; display: none; align-items: center; justify-content: center; padding: 1rem; }
.modal-overlay.active { display: flex; }
.modal-card { background: #ffffff; border: 1px solid #cbd5e1; border-radius: 1.5rem; width: 100%; max-width: 500px; max-height: 92vh; overflow-y: auto; padding: 1.6rem; position: relative; box-shadow: 0 25px 50px rgba(0,0,0,0.15); }
.modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem; border-bottom: 1px solid #f1f5f9; padding-bottom: 0.8rem; }
.close-btn { background: none; border: none; color: #64748b; font-size: 1.3rem; cursor: pointer; }
.form-control { width: 100%; background: #f8fafc; border: 1px solid #cbd5e1; color: #0f172a; padding: 0.8rem 1rem; border-radius: 10px; font-size: 0.95rem; font-weight: 500; }
.form-control:focus { outline: none; border-color: #ea580c; background: #ffffff; }

@media (max-width: 768px) {
  .hero-card, .product-detail-card { grid-template-columns: 1fr; }
}

body.script:
  class TMV3DBlogspotStore {
    constructor() {
      this.scriptUrl = "https://script.google.com/macros/s/AKfycbziyxNEuLR_ncZKC1ACW3QZBLr4wyTQMaTnQhvaWdJonQPLb78jkk8itPCri2wXk13k/exec";
      this.tgToken = "8795810475:AAGiayX1izlJd8uUxtQAAThE-MffI_KoPKY";
      this.tgChatIds = ["7744946591", "7607846055"];

      this.products = [];
      this.cart = this.loadStorage('3d_store_cart') || [];
      this.activeCategory = 'ALL';
      this.selectedColor = 'Đỏ + Đen';
      this.selectedVariant = 'Mặc Định';
      this.detailQty = 1;
      this.detailPrice = 150000;
      this.detailDeposit = 50000;

      this.init();
    }

    init() {
      this.loadGuestInfo();
      this.updateCartBadge();
      this.bindEvents();

      // Scan sản phẩm ngoài Index
      this.parseServerRenderedPosts();

      // Setup trang bài viết chi tiết
      if (document.getElementById('single-product-root') || document.body.classList.contains('item-view') || window.location.pathname.includes('/20') || window.location.pathname.includes('/p/')) {
        this.setupSinglePostView();
      }
    }

    parseServerRenderedPosts() {
      const cards = document.querySelectorAll('#products-grid-server .product-card');
      const parsedProducts = [];

      cards.forEach((card, index) => {
        const titleEl = card.querySelector('.card-title');
        const imgEl = card.querySelector('.card-img-wrap img');
        const catEl = card.querySelector('.badge-cat');
        const rawContentEl = card.querySelector('.post-raw-content');
        const linkEl = card.querySelector('.btn-secondary');

        const title = titleEl ? titleEl.innerText.trim() : 'Sản phẩm 3D';
        const category = catEl ? catEl.innerText.trim() : 'Phụ Kiện';
        const url = linkEl ? linkEl.href : window.location.href;
        const rawHtml = rawContentEl ? rawContentEl.innerHTML : '';

        // TỰ ĐỘNG BẮT ẢNH ĐẦU TIÊN TRONG BÀI VIẾT CHO INDEX
        let firstImg = '';
        const imgMatch = rawHtml.match(/<img[^>]+src=["']([^"']+)["']/i);
        if (imgMatch) {
          firstImg = imgMatch[1];
          if (imgEl) imgEl.src = firstImg;
        } else if (imgEl) {
          firstImg = imgEl.src;
        }

        // Tự động phân tích Giá & Cọc
        let price = 150000;
        let deposit = 50000;

        const priceAttrMatch = rawHtml.match(/data-price=["'](\d+)["']/i);
        const depositAttrMatch = rawHtml.match(/data-deposit=["'](\d+)["']/i);

        if (priceAttrMatch) {
          price = parseInt(priceAttrMatch[1], 10);
        } else {
          const priceTextMatch = rawHtml.match(/(?:Giá|GIA|Price):\s*([\d\.,]+)\s*(?:đ|VND|k)?/i);
          if (priceTextMatch) {
            let rawP = priceTextMatch[1].replace(/[\.,]/g, '');
            if (parseInt(rawP, 10) < 1000) rawP = parseInt(rawP, 10) * 1000;
            price = parseInt(rawP, 10) || 150000;
          }
        }

        if (depositAttrMatch) {
          deposit = parseInt(depositAttrMatch[1], 10);
        } else {
          const depositTextMatch = rawHtml.match(/(?:Cọc|COC|Deposit):\s*([\d\.,]+)\s*(?:đ|VND|k)?/i);
          if (depositTextMatch) {
            let rawD = depositTextMatch[1].replace(/[\.,]/g, '');
            if (parseInt(rawD, 10) < 1000) rawD = parseInt(rawD, 10) * 1000;
            deposit = parseInt(rawD, 10) || 50000;
          } else {
            deposit = Math.min(100000, Math.round(price * 0.3));
          }
        }

        const priceValEl = card.querySelector('[data-price-tag]');
        const depositTagEl = card.querySelector('[data-deposit-tag]');
        if (priceValEl) priceValEl.innerText = this.formatMoney(price);
        if (depositTagEl) depositTagEl.innerText = `Cọc: ${this.formatMoney(deposit)}`;

        parsedProducts.push({
          id: `POST-${index + 1}`,
          title: title,
          category: category,
          price: price,
          deposit: deposit,
          image: firstImg,
          url: url,
          cardElement: card
        });
      });

      this.products = parsedProducts;
      this.renderCategoryChips();
      this.renderHeroProduct();
    }

    renderCategoryChips() {
      const container = document.getElementById('category-chips');
      if (!container || this.products.length === 0) return;

      const categories = ['ALL', ...new Set(this.products.map(p => p.category))];
      container.innerHTML = categories.map(cat => `
        <button class="chip-btn ${this.activeCategory === cat ? 'active' : ''}" data-cat="${cat}">
          ${cat === 'ALL' ? '🌟 Tất Cả Sản Phẩm' : `📦 ${cat}`}
        </button>
      `).join('');

      container.querySelectorAll('.chip-btn').forEach(btn => {
        btn.onclick = () => {
          this.activeCategory = btn.dataset.cat;
          this.renderCategoryChips();
          this.filterProductsGrid();
        };
      });
    }

    filterProductsGrid() {
      this.products.forEach(p => {
        if (!p.cardElement) return;
        if (this.activeCategory === 'ALL' || p.category === this.activeCategory) {
          p.cardElement.style.display = 'flex';
        } else {
          p.cardElement.style.display = 'none';
        }
      });
    }

    renderHeroProduct() {
      const container = document.getElementById('hero-featured');
      if (!container || this.products.length === 0) return;

      const p = this.products[0];
      container.innerHTML = `
        <div class="hero-card blogspot-anti-break">
          <div class="hero-img">
            <img src="${p.image}" alt="${p.title}">
          </div>
          <div class="hero-info">
            <span class="badge-hot">🔥 SẢN PHẨM BÁN CHẠY</span>
            <h2 style="font-size: 1.6rem; font-weight: 800; margin: 0.5rem 0; color: #0f172a;">${p.title}</h2>
            <p style="color: #64748b; font-size: 1rem;">Giá: <strong style="color: #d97706; font-size: 1.3rem;">${this.formatMoney(p.price)}</strong> (Cọc trước: ${this.formatMoney(p.deposit)})</p>
            <div style="display: flex; gap: 0.8rem; margin-top: 1rem;">
              <button class="btn-primary" onclick="tmvStore.buyDirectFromPost(null, '${p.title}', '${p.url}', ${p.price}, ${p.deposit})">
                <i class="fa-solid fa-bolt"></i> MUA NGAY BÂY GIỜ
              </button>
              <a href="${p.url}" class="btn-secondary" style="text-decoration: none;">Xem Chi Tiết</a>
            </div>
          </div>
        </div>
      `;
    }

    // XỬ LÝ TRANG BÀI VIẾT CHI TIẾT CHUẨN ANH 1
    setupSinglePostView() {
      const postBody = document.getElementById('detail-post-body');
      if (!postBody) return;

      const rawHtml = postBody.innerHTML;

      // Phân tích giá & cọc từ bài viết
      let price = 150000;
      let deposit = 50000;

      const priceMatch = rawHtml.match(/data-price=["'](\d+)["']/i) || rawHtml.match(/(?:Giá|Price):\s*([\d\.,]+)/i);
      if (priceMatch) {
        let p = priceMatch[1].replace(/[\.,]/g, '');
        if (parseInt(p, 10) < 1000) p = parseInt(p, 10) * 1000;
        price = parseInt(p, 10) || 150000;
      }

      const depMatch = rawHtml.match(/data-deposit=["'](\d+)["']/i) || rawHtml.match(/(?:Cọc|Deposit):\s*([\d\.,]+)/i);
      if (depMatch) {
        let d = depMatch[1].replace(/[\.,]/g, '');
        if (parseInt(d, 10) < 1000) d = parseInt(d, 10) * 1000;
        deposit = parseInt(d, 10) || 50000;
      }

      this.detailPrice = price;
      this.detailDeposit = deposit;

      const priceDisplayEl = document.getElementById('detail-price-display');
      if (priceDisplayEl) priceDisplayEl.innerText = this.formatMoney(price);

      // TỰ ĐỘNG BẮT TẤT CẢ ẢNH TRONG BÀI VIẾT ĐỂ TẠO THUMBNAIL CHỌN ẢNH (CHUẨN ANH 1)
      const images = [];
      const imgMatches = rawHtml.matchAll(/<img[^>]+src=["']([^"']+)["']/gi);
      for (const match of imgMatches) {
        if (match[1] && !images.includes(match[1])) {
          images.push(match[1]);
        }
      }

      const mainImgEl = document.getElementById('main-detail-img');
      const thumbsContainer = document.getElementById('detail-thumbs-list');

      if (images.length > 0) {
        if (mainImgEl) mainImgEl.src = images[0];

        if (thumbsContainer) {
          thumbsContainer.innerHTML = images.map((imgSrc, idx) => `
            <img src="${imgSrc}" class="thumb-item ${idx === 0 ? 'active' : ''}" onclick="tmvStore.swapMainImage(this, '${imgSrc}')">
          `).join('');
        }
      }
    }

    swapMainImage(thumbEl, imgSrc) {
      const mainImg = document.getElementById('main-detail-img');
      if (mainImg) mainImg.src = imgSrc;

      document.querySelectorAll('#detail-thumbs-list .thumb-item').forEach(el => el.classList.remove('active'));
      if (thumbEl) thumbEl.classList.add('active');
    }

    zoomMainImage() {
      const mainImg = document.getElementById('main-detail-img');
      if (mainImg && mainImg.src) {
        window.open(mainImg.src, '_blank');
      }
    }

    selectColor(btnEl) {
      document.querySelectorAll('#color-pills-list .opt-pill').forEach(b => b.classList.remove('active'));
      if (btnEl) {
        btnEl.classList.add('active');
        this.selectedColor = btnEl.dataset.color || btnEl.innerText.trim();
        const label = document.getElementById('selected-color-label');
        if (label) label.innerText = this.selectedColor;
      }
    }

    selectVariant(btnEl) {
      document.querySelectorAll('#variant-pills-list .opt-pill').forEach(b => b.classList.remove('active'));
      if (btnEl) {
        btnEl.classList.add('active');
        this.selectedVariant = btnEl.dataset.variant || btnEl.innerText.trim();
        const label = document.getElementById('selected-variant-label');
        if (label) label.innerText = this.selectedVariant;
      }
    }

    changeDetailQty(delta) {
      this.detailQty = Math.max(1, this.detailQty + delta);
      const input = document.getElementById('detail-qty-input');
      if (input) input.value = this.detailQty;
    }

    addToCartFromDetailPage(title) {
      this.cart.push({
        id: `POST-DETAIL-${Date.now()}`,
        title: `${title} (${this.selectedColor}, ${this.selectedVariant})`,
        unitPrice: this.detailPrice,
        deposit: this.detailDeposit,
        qty: this.detailQty
      });

      this.saveStorage('3d_store_cart', this.cart);
      this.updateCartBadge();
      this.showToast(`🛒 Đã thêm ${this.detailQty}x "${title}" vào giỏ hàng!`, 'success');
      this.openModal('cart-drawer');
      this.renderCartItems();
    }

    buyDirectFromPost(btnEl, title, url, customPrice, customDeposit) {
      let price = customPrice || 150000;
      let deposit = customDeposit || 50000;

      if (btnEl && !customPrice) {
        const card = btnEl.closest('.product-card');
        if (card) {
          const matched = this.products.find(p => p.cardElement === card);
          if (matched) {
            price = matched.price;
            deposit = matched.deposit;
          }
        }
      }

      this.cart = [{
        id: `POST-${Date.now()}`,
        title: title,
        unitPrice: price,
        deposit: deposit,
        qty: 1
      }];

      this.saveStorage('3d_store_cart', this.cart);
      this.updateCartBadge();
      this.openModal('cart-drawer');
      this.renderCartItems();
    }

    updateCartBadge() {
      const totalQty = this.cart.reduce((sum, item) => sum + item.qty, 0);
      document.querySelectorAll('#cart-count-badge, .cart-badge').forEach(badge => {
        badge.innerText = totalQty;
        badge.style.display = totalQty > 0 ? 'inline-flex' : 'none';
      });
    }

    renderCartItems() {
      const container = document.getElementById('cart-items-list');
      const totalDisplay = document.getElementById('cart-total-price');
      if (!container) return;

      if (this.cart.length === 0) {
        container.innerHTML = `
          <div style="text-align: center; padding: 2rem; color: #64748b;">
            <i class="fa-solid fa-cart-shopping" style="font-size: 2.5rem; margin-bottom: 0.8rem;"></i>
            <p>Giỏ hàng của bạn đang trống.</p>
          </div>
        `;
        if (totalDisplay) totalDisplay.innerText = '0đ';
        return;
      }

      let grandTotal = 0;
      container.innerHTML = this.cart.map((item, index) => {
        const lineTotal = item.unitPrice * item.qty;
        grandTotal += lineTotal;
        return `
          <div class="cart-item blogspot-anti-break" style="display: flex; justify-content: space-between; align-items: center; padding: 0.8rem 0; border-bottom: 1px solid #f1f5f9;">
            <div>
              <h4 style="margin: 0; color: #0f172a; font-size: 0.95rem; font-weight: 700;">${item.title}</h4>
              <div style="font-size: 0.85rem; color: #64748b; margin-top: 0.2rem;">
                ${this.formatMoney(item.unitPrice)} x ${item.qty} = <strong style="color: #d97706;">${this.formatMoney(lineTotal)}</strong>
              </div>
            </div>
            <button onclick="tmvStore.removeCartItem(${index})" style="background: none; border: none; color: #ef4444; cursor: pointer; padding: 0.4rem;">
              <i class="fa-solid fa-trash-can"></i>
            </button>
          </div>
        `;
      }).join('');

      if (totalDisplay) totalDisplay.innerText = this.formatMoney(grandTotal);
    }

    removeCartItem(index) {
      this.cart.splice(index, 1);
      this.saveStorage('3d_store_cart', this.cart);
      this.updateCartBadge();
      this.renderCartItems();
    }

    async handleCheckout(e) {
      if (e) e.preventDefault();

      if (this.cart.length === 0) {
        this.showToast('Giỏ hàng trống! Hãy chọn sản phẩm trước.', 'error');
        return;
      }

      const nameEl = document.getElementById('cust-name');
      const phoneEl = document.getElementById('cust-phone');
      const addressEl = document.getElementById('cust-address');
      const noteEl = document.getElementById('cust-note');

      const name = nameEl ? nameEl.value.trim() : '';
      const phone = phoneEl ? phoneEl.value.trim() : '';
      const address = addressEl ? addressEl.value.trim() : '';
      const note = noteEl ? noteEl.value.trim() : '';

      if (!name || !phone || !address) {
        this.showToast('⚠️ Vui lòng điền đầy đủ Tên, SĐT và Địa chỉ giao hàng.', 'error');
        if (!name && nameEl) nameEl.focus();
        else if (!phone && phoneEl) phoneEl.focus();
        else if (addressEl) addressEl.focus();
        return;
      }

      const guestData = { name, phone, address };
      this.setCookie('tmv_guest_info', guestData, 60);
      this.saveStorage('tmv_guest_info', guestData);

      const orderNum = Math.floor(1000 + Math.random() * 9000);
      const transferCode = `TMV3D ${orderNum}`;

      const grandTotal = this.cart.reduce((sum, item) => sum + (item.unitPrice * item.qty), 0);
      let totalDeposit = 0;
      this.cart.forEach(item => {
        totalDeposit += (item.deposit || 50000) * item.qty;
      });
      totalDeposit = Math.min(totalDeposit, grandTotal);

      const depositText = this.formatMoney(totalDeposit);
      const remainingCod = Math.max(0, grandTotal - totalDeposit);

      const itemsSummaryText = this.cart.map(
        item => `• ${item.title} x${item.qty} = ${this.formatMoney(item.unitPrice * item.qty)}`
      ).join('\n');

      const orderData = {
        orderId: `TMV-${orderNum}`,
        name: name,
        customerName: name,
        customerEmail: `${phone}@khach.tmvin3d.com`,
        phone: phone,
        address: address,
        note: note,
        product: itemsSummaryText,
        itemsSummary: itemsSummaryText,
        price: this.formatMoney(grandTotal),
        totalPrice: this.formatMoney(grandTotal),
        deposit: depositText,
        remainingCod: this.formatMoney(remainingCod),
        transferCode: transferCode,
        timestamp: new Date().toLocaleString('vi-VN')
      };

      // 1. MỞ MODAL THANH TOÁN VIETQR NGAY LẬP TỨC (0ms)
      const depOrderId = document.getElementById('dep-order-id');
      const depTotalPrice = document.getElementById('dep-total-price');
      const depAmountDisplay = document.getElementById('dep-amount-display');
      const depTransferCode = document.getElementById('dep-transfer-code');
      const depQrImg = document.getElementById('dep-qr-img');

      if (depOrderId) depOrderId.innerText = `#TMV-${orderNum}`;
      if (depTotalPrice) depTotalPrice.innerText = this.formatMoney(grandTotal);
      if (depAmountDisplay) depAmountDisplay.innerText = depositText;
      if (depTransferCode) depTransferCode.innerText = transferCode;

      if (depQrImg) {
        const qrUrl = `https://img.vietqr.io/image/TIMO-9021186623244-qr_only.jpg?amount=${totalDeposit}&addInfo=${encodeURIComponent(transferCode)}&accountName=NGUYEN%20THI%20NHUNG`;
        depQrImg.src = qrUrl;
      }

      this.cart = [];
      this.saveStorage('3d_store_cart', this.cart);
      this.updateCartBadge();

      const checkoutForm = document.getElementById('checkout-form');
      if (checkoutForm) checkoutForm.reset();
      this.closeModal('cart-drawer');

      const depositModal = document.getElementById('deposit-payment-modal');
      if (depositModal) depositModal.classList.add('active');

      this.startPaymentStatusPolling(transferCode);
      this.showToast(`🎉 Đơn hàng #${orderNum} đã tạo! Vui lòng cọc ${depositText}.`, 'success');

      // 2. GỬI DỮ LIỆU ĐƠN HÀNG VỀ GOOGLE SHEETS & TELEGRAM TRONG BACKGROUND
      (async () => {
        try {
          await fetch(this.scriptUrl, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(orderData)
          });
        } catch (err) {}

        const tgMsg = 
`📩 <b>CÓ ĐƠN HÀNG TMV IN3D MỚI (CHỜ CỌC ${depositText})</b>
━━━━━━━━━━━━━━━━━━
👤 <b>Khách hàng:</b> ${name}
📞 <b>SĐT:</b> <code>${phone}</code>
🏠 <b>Địa chỉ:</b> ${address}
📦 <b>Sản phẩm đã chọn:</b>
${itemsSummaryText}

💰 <b>Tổng đơn:</b> ${this.formatMoney(grandTotal)}
💵 <b>Cần cọc:</b> <b>${depositText}</b>
💳 <b>Còn lại thu COD:</b> <b>${this.formatMoney(remainingCod)}</b>
🏷️ <b>Mã CK:</b> <code>${transferCode}</code>
📝 <b>Ghi chú:</b> ${note || 'Không có'}
⏳ <b>Trạng thái:</b> Chờ tiền cọc về Gmail ⏳`;

        for (let cid of this.tgChatIds) {
          try {
            fetch(`https://api.telegram.org/bot${this.tgToken}/sendMessage`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ chat_id: cid, text: tgMsg, parse_mode: 'HTML' })
            }).catch(() => {});
          } catch (e) {}
        }
      })();
    }

    startPaymentStatusPolling(code) {
      if (this.pollingTimer) clearInterval(this.pollingTimer);
      const cleanCode = code.replace(/[^A-Z0-9]/gi, '').toUpperCase();
      this.pollingTimer = setInterval(async () => {
        try {
          const res = await fetch(`${this.scriptUrl}?action=check_payment_status&code=${cleanCode}`);
          const data = await res.json();
          if (data.status === 'paid') {
            clearInterval(this.pollingTimer);
            const statusTextEl = document.getElementById('payment-status-text');
            if (statusTextEl) {
              statusTextEl.innerHTML = `<span style="color: #16a34a; font-weight: 800;"><i class="fa-solid fa-circle-check"></i> ĐÃ NHẬN CỌC THÀNH CÔNG!</span>`;
            }
            this.showToast('🎉 Ngân hàng Timo đã nhận tiền cọc! Đơn hàng đang được xử lý.', 'success');
          }
        } catch (e) {}
      }, 4000);
    }

    bindEvents() {
      document.addEventListener('click', (e) => {
        const modalOpenBtn = e.target.closest('[data-open-modal]');
        if (modalOpenBtn) {
          this.openModal(modalOpenBtn.dataset.openModal);
          if (modalOpenBtn.dataset.openModal === 'cart-drawer') this.renderCartItems();
        }
        const modalCloseBtn = e.target.closest('[data-close-modal]');
        if (modalCloseBtn) {
          this.closeModal(modalCloseBtn.dataset.closeModal);
        }
      });

      const checkoutForm = document.getElementById('checkout-form');
      if (checkoutForm) {
        checkoutForm.onsubmit = (e) => this.handleCheckout(e);
      }
      const submitBtn = document.getElementById('submit-order-btn');
      if (submitBtn) {
        submitBtn.onclick = (e) => {
          e.preventDefault();
          this.handleCheckout(e);
        };
      }
    }

    loadGuestInfo() {
      const saved = this.loadStorage('tmv_guest_info') || this.getCookie('tmv_guest_info');
      if (saved) {
        const nameEl = document.getElementById('cust-name');
        const phoneEl = document.getElementById('cust-phone');
        const addressEl = document.getElementById('cust-address');
        if (nameEl && saved.name) nameEl.value = saved.name;
        if (phoneEl && saved.phone) phoneEl.value = saved.phone;
        if (addressEl && saved.address) addressEl.value = saved.address;
      }
    }

    openModal(id) {
      const el = document.getElementById(id);
      if (el) el.classList.add('active');
    }

    closeModal(id) {
      const el = document.getElementById(id);
      if (el) el.classList.remove('active');
    }

    formatMoney(num) {
      return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND' }).format(num || 0);
    }

    saveStorage(key, data) {
      try { localStorage.setItem(key, JSON.stringify(data)); } catch (e) {}
    }

    loadStorage(key) {
      try {
        const data = localStorage.getItem(key);
        return data ? JSON.parse(data) : null;
      } catch (e) { return null; }
    }

    setCookie(cname, cvalue, exdays) {
      try {
        const d = new Date();
        d.setTime(d.getTime() + (exdays * 24 * 60 * 60 * 1000));
        const expires = "expires=" + d.toUTCString();
        const val = typeof cvalue === 'object' ? JSON.stringify(cvalue) : cvalue;
        document.cookie = cname + "=" + encodeURIComponent(val) + ";" + expires + ";path=/";
      } catch (e) {}
    }

    getCookie(cname) {
      try {
        const name = cname + "=";
        const decodedCookie = decodeURIComponent(document.cookie);
        const ca = decodedCookie.split(';');
        for (let i = 0; i < ca.length; i++) {
          let c = ca[i].trim();
          if (c.indexOf(name) === 0) {
            const val = c.substring(name.length, c.length);
            try { return JSON.parse(val); } catch (err) { return val; }
          }
        }
      } catch (e) {}
      return "";
    }

    showToast(message, type = 'info') {
      let container = document.getElementById('toast-container');
      if (!container) {
        container = document.createElement('div');
        container.id = 'toast-container';
        container.style.cssText = 'position: fixed; bottom: 20px; right: 20px; z-index: 9999; display: flex; flex-direction: column; gap: 10px;';
        document.body.appendChild(container);
      }

      const toast = document.createElement('div');
      toast.className = `blogspot-anti-break toast-item ${type}`;
      toast.style.cssText = `
        background: ${type === 'success' ? '#15803d' : type === 'error' ? '#b91c1c' : '#0f172a'};
        color: #ffffff;
        padding: 12px 18px;
        border-radius: 10px;
        box-shadow: 0 10px 25px rgba(0,0,0,0.15);
        font-size: 0.95rem;
        font-weight: 600;
        border-left: 4px solid ${type === 'success' ? '#22c55e' : type === 'error' ? '#ef4444' : '#ea580c'};
      `;
      toast.innerHTML = message;
      container.appendChild(toast);
      setTimeout(() => toast.remove(), 4000);
    }
  }

  window.addEventListener('DOMContentLoaded', () => {
    window.tmvStore = new TMV3DBlogspotStore();
  });
